        EQ("POST без ключа…", "POST without a key is…", ["не ідемпотентний", "безпечний як GET", "завжди можна автоповторювати", "тотожний DELETE"], 0, "Ризик дубліката.", "A risk of a duplicate."),
        EQ("Idempotency-Key на повторі того самого тіла…", "An Idempotency-Key on a retry of the same body…", ["повертає збережену відповідь", "створює другий платіж", "ігнорується", "завжди 401"], 0, "Сенс ключа.", "The point of the key."),
        EQ("Той самий ключ, інше тіло…", "The same key, a different body…", ["конфлікт 409/422", "тихе друге створення", "201 завжди", "кеш 304"], 0, "Ключ зайнятий.", "The key is taken."),
